'use client';

/**
 * `app-sidebar.tsx` — the dashboard-01 block's navigation rail: an AI-platform-flavored nav-main
 * (Dashboard / Agents / Tasks / Usage / Settings) plus a nav-user footer (`Avatar` +
 * `DropdownMenu`). Composes `AppShellSidebar`/`Sidebar`'s public API only — no new primitive.
 *
 * 'use client' — the active-nav-item comparison is presentational-only (no router coupling), but
 * the footer's `DropdownMenu` is interactive, so the whole file crosses the client boundary.
 * `DashboardPage` (`../page.tsx`) stays server-safe by importing this as a client leaf, exactly
 * like `AppShellSkeleton`'s doc describes for `SidebarMenuSkeleton`.
 *
 * Zero Next.js imports (house rule): nav links render as plain `<a>` via `SidebarMenuButton`'s
 * `render` prop — swap in your router's `Link` at the call site (`render={<Link href={...} />}`)
 * without touching this file's structure.
 */

import {
  BarChart3,
  Bot,
  ChevronsUpDown,
  CreditCard,
  LayoutDashboard,
  ListChecks,
  LogOut,
  Settings,
  User,
  type LucideIcon,
} from 'lucide-react';
import { AppShellSidebar } from '@/components/ui/app-shell';
import { Avatar } from '@/components/ui/avatar';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from '@/components/ui/sidebar';

interface NavItem {
  key: 'dashboard' | 'agents' | 'tasks' | 'usage' | 'settings';
  label: string;
  href: string;
  icon: LucideIcon;
}

const NAV_ITEMS: readonly NavItem[] = [
  { key: 'dashboard', label: 'Dashboard', href: '/dashboard', icon: LayoutDashboard },
  { key: 'agents', label: 'Agents', href: '/dashboard/agents', icon: Bot },
  { key: 'tasks', label: 'Tasks', href: '/dashboard/tasks', icon: ListChecks },
  { key: 'usage', label: 'Usage', href: '/dashboard/usage', icon: BarChart3 },
  { key: 'settings', label: 'Settings', href: '/dashboard/settings', icon: Settings },
];

export interface AppSidebarUser {
  name: string;
  email: string;
  /** Resolved, public avatar URL — see `Avatar`'s doc; this component does not resolve storage keys. */
  avatarUrl?: string;
}

export interface AppSidebarProps {
  /** Which nav item is current — highlights it and sets `aria-current="page"`. */
  activeKey?: NavItem['key'];
  /** The signed-in user shown in the footer menu. */
  user?: AppSidebarUser;
  /** Called when "Log out" is selected — presentational only, no session logic here. */
  onLogout?: () => void;
}

const DEFAULT_USER: AppSidebarUser = { name: 'Ada Lovelace', email: 'ada@vegastack.com' };

function initialsOf(name: string): string {
  return name
    .split(' ')
    .filter(Boolean)
    .map((part) => part[0])
    .slice(0, 2)
    .join('')
    .toUpperCase();
}

/**
 * `AppSidebar` — `AppShellSidebar` composed with the block's nav-main + nav-user footer. The
 * `[view-transition-name:dashboard-shell-sidebar]` arbitrary property (Tailwind v4 native
 * arbitrary-property syntax — a CSS custom-ident, not a hex/px literal, so it stays clean under
 * design-lint's arbitrary-value contract) marks the rail as a STABLE region for the block's View
 * Transitions wiring — see the block's docs page "View Transitions" section for the full
 * mechanism and the required `next.config.js` flag.
 */
export function AppSidebar({ activeKey = 'dashboard', user = DEFAULT_USER, onLogout }: AppSidebarProps) {
  const initials = initialsOf(user.name);

  return (
    <AppShellSidebar className="[view-transition-name:dashboard-shell-sidebar]">
      <SidebarHeader>
        <div className="flex items-center gap-2 px-2 py-1.5">
          <div
            aria-hidden
            className="flex size-(--icon-feature) shrink-0 items-center justify-center rounded-md bg-primary text-primary-foreground"
          >
            <Bot className="size-(--icon-default)" />
          </div>
          <span className="truncate text-label font-medium text-foreground group-data-[state=collapsed]/sidebar:hidden">
            VegaStack AI
          </span>
        </div>
      </SidebarHeader>

      <SidebarContent>
        <SidebarGroup>
          <SidebarGroupLabel>Platform</SidebarGroupLabel>
          <SidebarMenu>
            {NAV_ITEMS.map((item) => (
              <SidebarMenuItem key={item.key}>
                <SidebarMenuButton isActive={activeKey === item.key} render={<a href={item.href} />}>
                  <item.icon />
                  <span>{item.label}</span>
                </SidebarMenuButton>
              </SidebarMenuItem>
            ))}
          </SidebarMenu>
        </SidebarGroup>
      </SidebarContent>

      <SidebarFooter>
        <DropdownMenu>
          <DropdownMenuTrigger className="flex w-full items-center gap-2 rounded-md p-2 text-left transition-colors duration-fast ease-standard hover:bg-sidebar-accent hover:text-sidebar-accent-foreground">
            <Avatar
              size="sm"
              src={user.avatarUrl}
              alt={user.avatarUrl ? user.name : ''}
              fallback={initials}
            />
            {/* min-w-0 on the label column — the sidebar footer row's trailing chevron is a fixed
                sibling, so the name/email column needs min-w-0 to truncate instead of overflowing
                (the same flex-discipline footgun the app-shell audit flags for stat cards/cards). */}
            <span className="flex min-w-0 flex-1 flex-col group-data-[state=collapsed]/sidebar:hidden">
              <span className="truncate text-sm font-medium text-sidebar-foreground">{user.name}</span>
              <span className="truncate text-sm text-muted-foreground">{user.email}</span>
            </span>
            <ChevronsUpDown
              aria-hidden
              className="size-(--icon-inline) shrink-0 text-muted-foreground group-data-[state=collapsed]/sidebar:hidden"
            />
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start" side="top" className="w-56">
            <DropdownMenuLabel>{user.name}</DropdownMenuLabel>
            <DropdownMenuSeparator />
            <DropdownMenuItem>
              <User />
              Profile
            </DropdownMenuItem>
            <DropdownMenuItem>
              <CreditCard />
              Billing
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem variant="destructive" onClick={onLogout}>
              <LogOut />
              Log out
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </SidebarFooter>
    </AppShellSidebar>
  );
}

// @vegastack dashboard-01@0.1.0 sha256-Y/pYrxWGCPZZ2pSM0tGLrww5YEd4w6EfahXXRxkN/tA=

'use client';

/**
 * `stat-cards.tsx` — the dashboard-01 block's four-up metrics row (audit §e item 2): "Active
 * agents" / "Tasks completed today" / "API calls (24h)" / "Avg. response time", each a `Card`
 * with a label + delta `Badge` row and a `font-mono` `AnimatedNumber` value.
 *
 * 'use client' — `AnimatedNumber` is a client leaf (tween + `prefers-reduced-motion` hook).
 */

import { ArrowDown, ArrowUp, Minus } from 'lucide-react';
import { AnimatedNumber } from '@/components/ui/animated-number';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';

export interface StatCardDatum {
  /** Stable identifier — used as the React key. */
  key: string;
  label: string;
  value: number;
  /** Percentage change vs. the prior period. Positive = up (`success`), negative = down (`destructive`), 0 = flat. */
  delta: number;
  /** Formatting hint for `value` — omit for a plain grouped integer, or `'ms'` for a millisecond duration. */
  unit?: 'ms';
}

export interface StatCardsProps {
  stats: StatCardDatum[];
  /** Shows 4 skeleton placeholder cards instead of `stats` — the region's own loading state. */
  loading?: boolean;
}

function formatDelta(delta: number): string {
  return `${Math.abs(delta).toLocaleString(undefined, { maximumFractionDigits: 1 })}%`;
}

/**
 * `StatCards` — renders directly inside `AppShellContent`'s `@container/app-shell-content`
 * (audit §e item 2): `grid-cols-1` on narrow content, `@sm/app-shell-content:grid-cols-2`,
 * `@lg/app-shell-content:grid-cols-4` — driven by the CONTENT region's own width (sidebar
 * collapse-aware via a Tailwind v4 native container query), not the viewport, since collapsing
 * the sidebar changes available width independent of viewport size (`app-shell.tsx`'s own doc).
 */
export function StatCards({ stats, loading = false }: StatCardsProps) {
  return (
    <div
      data-slot="dashboard-stat-cards"
      className="grid grid-cols-1 gap-4 @sm/app-shell-content:grid-cols-2 @lg/app-shell-content:grid-cols-4"
    >
      {loading
        ? Array.from({ length: 4 }, (_, i) => (
            <Card key={i} aria-hidden="true">
              <CardHeader>
                <Skeleton className="h-4 w-24" />
              </CardHeader>
              <CardContent>
                <Skeleton className="h-9 w-20" />
              </CardContent>
            </Card>
          ))
        : stats.map((stat) => {
            const trend = stat.delta > 0 ? 'up' : stat.delta < 0 ? 'down' : 'flat';
            return (
              <Card key={stat.key} data-slot="dashboard-stat-card">
                <CardHeader>
                  {/* min-w-0 on the label+badge row (audit §d footgun) — `Card`'s header carries no
                      min-w-0 by default, so a fixed-width trailing badge would force the row to
                      overflow instead of letting the label truncate. */}
                  <div className="flex min-w-0 items-center justify-between gap-2">
                    <CardTitle className="min-w-0 truncate text-label-sm font-normal text-muted-foreground">
                      {stat.label}
                    </CardTitle>
                    <Badge
                      variant="subtle"
                      intent={trend === 'up' ? 'success' : trend === 'down' ? 'destructive' : 'default'}
                      className="shrink-0"
                    >
                      {trend === 'up' ? <ArrowUp /> : trend === 'down' ? <ArrowDown /> : <Minus />}
                      {formatDelta(stat.delta)}
                    </Badge>
                  </div>
                </CardHeader>
                <CardContent>
                  <AnimatedNumber
                    value={stat.value}
                    format={
                      stat.unit === 'ms'
                        ? { style: 'unit', unit: 'millisecond', unitDisplay: 'short' }
                        : { maximumFractionDigits: 0 }
                    }
                    className="font-mono text-2xl text-foreground"
                  />
                </CardContent>
              </Card>
            );
          })}
    </div>
  );
}

// @vegastack dashboard-01@0.1.0 sha256-Y/pYrxWGCPZZ2pSM0tGLrww5YEd4w6EfahXXRxkN/tA=

'use client';

/**
 * `dashboard-chart.tsx` — the dashboard-01 block's "Usage over time" card (audit §e item 3):
 * `ChartContainer` + a Recharts `AreaChart` over static, deterministic data (`requests`/`errors`
 * for the last 7 days), themed with the `chart-1`/`chart-2` tokens. `accessibilityLayer` is set
 * explicitly per `chart.tsx`'s own doc, so the chart is keyboard-navigable, not just a static image.
 *
 * 'use client' — Recharts renders into the DOM (ResizeObserver-driven `ResponsiveContainer`).
 */

import * as React from 'react';
import { Area, AreaChart, CartesianGrid, XAxis, YAxis } from 'recharts';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { ChartContainer, ChartTooltip, ChartTooltipContent, type ChartConfig } from '@/components/ui/chart';
import { Skeleton } from '@/components/ui/skeleton';

export interface UsagePoint {
  date: string;
  requests: number;
  errors: number;
}

export interface DashboardChartProps {
  data: UsagePoint[];
  /** Shows a skeleton placeholder instead of the chart — the region's own loading state. */
  loading?: boolean;
}

const chartConfig = {
  requests: { label: 'Requests', color: 'chart-1' },
  errors: { label: 'Errors', color: 'chart-2' },
} satisfies ChartConfig;

/** `DashboardChart` — a `Card` wrapping the themed area chart, or its loading placeholder. */
export function DashboardChart({ data, loading = false }: DashboardChartProps) {
  return (
    <Card data-slot="dashboard-chart">
      <CardHeader>
        <CardTitle>Usage over time</CardTitle>
        <CardDescription>Requests and errors for the last 7 days.</CardDescription>
      </CardHeader>
      <CardContent>
        {loading ? (
          <Skeleton shape="rect" className="h-64 w-full" aria-hidden="true" />
        ) : (
          <ChartContainer config={chartConfig} className="aspect-auto h-64 w-full">
            <AreaChart accessibilityLayer data={data} margin={{ left: 0, right: 0 }}>
              <CartesianGrid vertical={false} stroke="var(--border)" />
              <XAxis dataKey="date" tickLine={false} axisLine={false} tickMargin={8} />
              <YAxis tickLine={false} axisLine={false} tickMargin={8} width={44} />
              <ChartTooltip cursor={{ stroke: 'var(--border)' }} content={<ChartTooltipContent />} />
              <Area
                dataKey="requests"
                type="monotone"
                fill="var(--color-requests)"
                fillOpacity={0.2}
                stroke="var(--color-requests)"
                strokeWidth={2}
              />
              <Area
                dataKey="errors"
                type="monotone"
                fill="var(--color-errors)"
                fillOpacity={0.2}
                stroke="var(--color-errors)"
                strokeWidth={2}
              />
            </AreaChart>
          </ChartContainer>
        )}
      </CardContent>
    </Card>
  );
}

// @vegastack dashboard-01@0.1.0 sha256-Y/pYrxWGCPZZ2pSM0tGLrww5YEd4w6EfahXXRxkN/tA=

'use client';

/**
 * `recent-activity.tsx` — the dashboard-01 block's recent-activity `DataList` (audit §e item 4):
 * task/agent name (`IconText`), status (`StatusIcon`), started (`RelativeTime`), duration
 * (`TableCellText`, `mono`). Wires `DataList`'s own built-in `loading` skeleton rows and a
 * custom `emptyState` ("No activity yet" + a CTA).
 *
 * 'use client' — `DataList`, `IconText`/`TruncatedText`, and `RelativeTime` are all client leaves
 * (ResizeObserver / Tooltip / timers).
 */

import * as React from 'react';
import { FileText, ListChecks } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DataList, type DataListColumn } from '@/components/ui/data-list';
import { Empty, EmptyContent, EmptyDescription, EmptyHeader, EmptyMedia, EmptyTitle } from '@/components/ui/empty';
import { RelativeTime } from '@/components/ui/relative-time';
import { StatusIcon, type StatusIconProps } from '@/components/ui/status-icon';
import { IconText, TableCellText } from '@/components/ui/truncated-text';

export interface ActivityRow {
  id: string;
  name: string;
  status: NonNullable<StatusIconProps['status']>;
  /** ISO instant the task/run started. */
  startedAt: string;
  durationMs: number;
}

/**
 * Fixed reference instant the "started" column's `RelativeTime` is measured against.
 *
 * **Determinism investigation (house rule: no `Date.now()`/`Math.random()` anywhere a VRT
 * screenshot can see):** `RelativeTime` (`packages/ui/registry/ui/relative-time.tsx`) defaults to
 * the live clock (`Date.now()`) and re-renders on a timer. Its API exposes exactly the escape
 * hatch this block needs — a `now` prop (epoch ms) that replaces the live clock for the "X ago"
 * computation, paired with `refresh={false}` to also suppress the internal `setTimeout` re-render
 * loop (`isControlled = now !== undefined` short-circuits the timer effect in the source). Passing
 * both together is `RelativeTime`'s documented deterministic mode — every render, at any wall-clock
 * time, produces the identical "X ago" string. `DASHBOARD_NOW_MS` matches `data.json`'s
 * `generatedAt` so the demo's relative strings stay sensible (e.g. "6 minutes ago") without ever
 * reading the real clock.
 */
const DASHBOARD_NOW_MS = Date.parse('2026-07-14T09:00:00.000Z');

function formatDuration(ms: number): string {
  if (ms < 1000) return `${ms}ms`;
  const totalSeconds = Math.round(ms / 1000);
  if (totalSeconds < 60) return `${totalSeconds}s`;
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${minutes}m ${seconds}s`;
}

const columns: DataListColumn<ActivityRow>[] = [
  {
    key: 'name',
    header: 'Task',
    render: (row) => <IconText icon={<FileText />} text={row.name} />,
  },
  {
    key: 'status',
    header: 'Status',
    render: (row) => (
      <span className="flex items-center gap-1.5">
        <StatusIcon status={row.status} size="sm" />
        <span className="text-base text-foreground">
          {row.status === 'progress' ? 'In progress' : row.status === 'todo' ? 'To do' : row.status}
        </span>
      </span>
    ),
  },
  {
    key: 'startedAt',
    header: 'Started',
    render: (row) => (
      <RelativeTime
        date={row.startedAt}
        now={DASHBOARD_NOW_MS}
        refresh={false}
        className="text-muted-foreground"
      />
    ),
  },
  {
    key: 'durationMs',
    header: 'Duration',
    align: 'end',
    render: (row) => <TableCellText text={formatDuration(row.durationMs)} mono />,
  },
];

export interface RecentActivityProps {
  data: ActivityRow[];
  /** Shows `DataList`'s built-in skeleton rows instead of `data` — the region's own loading state. */
  loading?: boolean;
}

/** `RecentActivity` — the recent-activity `DataList`, per audit §e item 4. */
export function RecentActivity({ data, loading = false }: RecentActivityProps) {
  return (
    <DataList
      data-slot="dashboard-recent-activity"
      columns={columns}
      data={data}
      getRowId={(row) => row.id}
      loading={loading}
      loadingRows={5}
      emptyState={
        <Empty size="sm">
          <EmptyHeader>
            <EmptyMedia>
              <ListChecks />
            </EmptyMedia>
            <EmptyTitle>No activity yet</EmptyTitle>
            <EmptyDescription>Tasks and agent runs will show up here once they start.</EmptyDescription>
          </EmptyHeader>
          <EmptyContent>
            <Button size="sm" variant="outline" render={<a href="/dashboard/tasks" />}>
              View tasks
            </Button>
          </EmptyContent>
        </Empty>
      }
    />
  );
}
